**What this code covers**

- A minimal but complete agent built from scratch.
- Register a tool with its schema and implementation.
- Run the agent on a user message.
- Reset conversation history but keep tools registered.
- Append assistant message to conversation
- If no tool calls, we're done — return the final answer
- Execute each tool call and append results
- Create and configure the agent

**Defines:** `Agent`, `tool()`, `register_tools()`, `calculator()`, `get_current_time()`

### Step 1: The Core Agent Class

```python
import json
import time
from openai import OpenAI

class Agent:
    """A minimal but complete agent built from scratch."""

    def __init__(self, system_prompt, model="gpt-4o"):
        self.client = OpenAI()
        self.model = model
        self.system_prompt = system_prompt
        self.messages = [{"role": "system", "content": system_prompt}]
        self.tools = {}              # name -> callable
        self.tool_definitions = []   # list of OpenAI tool dicts
        self.max_iterations = 15
        self.total_tokens_used = 0

    def register_tool(self, name, description, parameters, func):
        """Register a tool with its schema and implementation."""
        self.tools[name] = func
        self.tool_definitions.append({
            "type": "function",
            "function": {
                "name": name,
                "description": description,
                "parameters": parameters,
            }
        })

    def run(self, user_message):
        """Run the agent on a user message. Returns the final text response."""
        self.messages.append({"role": "user", "content": user_message})

        for i in range(self.max_iterations):
            response = self.client.chat.completions.create(
                model=self.model,
                messages=self.messages,
                tools=self.tool_definitions if self.tool_definitions else None,
            )

            # Track token usage
            if response.usage:
                self.total_tokens_used += response.usage.total_tokens

            choice = response.choices[0]
            assistant_message = choice.message

            # Append assistant message to conversation
            msg_dict = {"role": "assistant", "content": assistant_message.content}
            if assistant_message.tool_calls:
                msg_dict["tool_calls"] = [
                    tc.model_dump() for tc in assistant_message.tool_calls
                ]
            self.messages.append(msg_dict)

            # If no tool calls, we're done — return the final answer
            if not assistant_message.tool_calls:
                return assistant_message.content

            # Execute each tool call and append results
            for tool_call in assistant_message.tool_calls:
                fn_name = tool_call.function.name
                fn_args = json.loads(tool_call.function.arguments)
                tool_call_id = tool_call.id

                print(f"  [Tool Call] {fn_name}({json.dumps(fn_args)})")

                try:
                    result = self.tools[fn_name](**fn_args)
                    result_str = json.dumps(result) if not isinstance(result, str) else result
                except Exception as e:
                    result_str = json.dumps({"error": str(e)})
                    print(f"  [Tool Error] {fn_name}: {e}")

                self.messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call_id,
                    "content": result_str,
                })

        return "[Agent] Maximum iterations reached without a final answer."

    def reset(self):
        """Reset conversation history but keep tools registered."""
        self.messages = [{"role": "system", "content": self.system_prompt}]
        self.total_tokens_used = 0
```

### Step 2: A Decorator-Based Tool Registration System

```python
def tool(name, description, parameters):
    """Decorator to register a function as an agent tool.

    Usage:
        @tool("get_weather", "Get the current weather for a city", {
            "type": "object",
            "properties": {
                "city": {"type": "string", "description": "The city name"},
            },
            "required": ["city"],
        })
        def get_weather(city: str) -> dict:
            ...
    """
    def decorator(func):
        func._tool_meta = {
            "name": name,
            "description": description,
            "parameters": parameters,
        }
        return func
    return decorator

def register_tools(agent, *tool_funcs):
    """Register all decorated tool functions with the agent."""
    for func in tool_funcs:
        meta = func._tool_meta
        agent.register_tool(meta["name"], meta["description"], meta["parameters"], func)
```

### Step 3: Putting It All Together

```python
import math

@tool(
    name="calculator",
    description="Evaluate a mathematical expression and return the result.",
    parameters={
        "type": "object",
        "properties": {
            "expression": {
                "type": "string",
                "description": "A valid Python math expression, e.g. '2 ** 10' or 'sin(pi)'",
            }
        },
        "required": ["expression"],
    },
)
def calculator(expression: str) -> str:
    """Safely evaluate a math expression using only allowed names."""
    allowed_names = {
        "abs": abs, "round": round, "min": min, "max": max,
        "sum": sum, "pow": pow, "int": int, "float": float,
        "sqrt": math.sqrt, "log": math.log, "sin": math.sin,
        "cos": math.cos, "tan": math.tan, "pi": math.pi, "e": math.e,
    }
    try:
        result = eval(expression, {"__builtins__": {}}, allowed_names)  # noqa: S307
        return str(result)
    except Exception as e:
        return f"Error: {e}"

@tool(
    name="get_current_time",
    description="Get the current date and time.",
    parameters={
        "type": "object",
        "properties": {},
        "required": [],
    },
)
def get_current_time() -> str:
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).isoformat()

# --- Create and configure the agent ---
agent = Agent(
    system_prompt=(
        "You are a helpful assistant with access to tools. "
        "Use tools when needed to answer questions accurately. "
        "When you have the final answer, respond directly without calling more tools."
    )
)
register_tools(agent, calculator, get_current_time)

# --- Run it ---
result = agent.run("What is 2 to the power of 20, and what time is it right now in UTC?")
print(f"\nFinal answer: {result}")
print(f"Total tokens used: {agent.total_tokens_used}")
```

**Expected output (structure):**

```
  [Tool Call] calculator({"expression": "2 ** 20"})
  [Tool Call] get_current_time({})
Final answer: 2 to the power of 20 is 1,048,576. The current UTC time is 2025-01-15T10:30:00+00:00.
Total tokens used: 487
```

**What this code covers**

- A ReAct (Reason + Act) agent with thought/action/observation loop.
- Decorator to register a tool.
- Execute the ReAct loop and return the final answer.
- Simulated web search — replace with real API in production.
- Build message dict for conversation history
- No tool calls? Agent is done — return final answer.
- Execute all tool calls from this turn
- Example usage with a research assistant

**Defines:** `ReActAgent`, `search_web()`, `get_page_content()`

The **ReAct** (Reasoning + Acting) pattern interleaves structured *thought*, *action*, and *observation* steps. Here's a complete implementation:

```python
import json
import time
import functools
from typing import Any, Callable
from openai import OpenAI

class ReActAgent:
    """A ReAct (Reason + Act) agent with thought/action/observation loop."""

    def __init__(
        self,
        system_prompt: str,
        model: str = "gpt-4o",
        max_iterations: int = 10,
        tool_timeout: float = 30.0,
        verbose: bool = True,
    ):
        self.client = OpenAI()
        self.model = model
        self.system_prompt = system_prompt
        self.max_iterations = max_iterations
        self.tool_timeout = tool_timeout
        self.verbose = verbose
        self.tools: dict[str, Callable] = {}
        self.tool_schemas: list[dict] = []
        self.messages: list[dict] = []
        self.token_usage = {"prompt": 0, "completion": 0, "total": 0}
        self.trace: list[dict] = []  # Full execution trace for debugging

    def tool(self, name: str, description: str, parameters: dict):
        """Decorator to register a tool."""
        def decorator(func: Callable) -> Callable:
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                start = time.monotonic()
                try:
                    result = func(*args, **kwargs)
                    elapsed = time.monotonic() - start
                    self._log(f"    -> {result!r} ({elapsed:.2f}s)")
                    return result
                except Exception as e:
                    elapsed = time.monotonic() - start
                    self._log(f"    -> ERROR: {e} ({elapsed:.2f}s)")
                    return {"error": str(e)}
            self.tools[name] = wrapper
            self.tool_schemas.append({
                "type": "function",
                "function": {
                    "name": name,
                    "description": description,
                    "parameters": parameters,
                }
            })
            return wrapper
        return decorator

    def _log(self, message: str):
        if self.verbose:
            print(message)

    def _track_tokens(self, usage):
        if usage:
            self.token_usage["prompt"] += usage.prompt_tokens
            self.token_usage["completion"] += usage.completion_tokens
            self.token_usage["total"] += usage.total_tokens

    def run(self, user_message: str) -> str:
        """Execute the ReAct loop and return the final answer."""
        self.messages = [
            {"role": "system", "content": self.system_prompt},
            {"role": "user", "content": user_message},
        ]
        self.trace = []

        self._log(f"User: {user_message}")
        self._log("=" * 60)

        for iteration in range(1, self.max_iterations + 1):
            self._log(f"\n--- Iteration {iteration}/{self.max_iterations} ---")

            response = self.client.chat.completions.create(
                model=self.model,
                messages=self.messages,
                tools=self.tool_schemas if self.tool_schemas else None,
                temperature=0.1,
            )
            self._track_tokens(response.usage)

            choice = response.choices[0]
            assistant_msg = choice.message

            # Build message dict for conversation history
            msg_dict = {"role": "assistant", "content": assistant_msg.content}
            if assistant_msg.tool_calls:
                msg_dict["tool_calls"] = [
                    tc.model_dump() for tc in assistant_msg.tool_calls
                ]
            self.messages.append(msg_dict)

            # Record in trace
            self.trace.append({
                "iteration": iteration,
                "content": assistant_msg.content,
                "tool_calls": [
                    {"name": tc.function.name, "args": tc.function.arguments}
                    for tc in (assistant_msg.tool_calls or [])
                ],
            })

            # No tool calls? Agent is done — return final answer.
            if not assistant_msg.tool_calls:
                self._log(f"\nAgent: {assistant_msg.content}")
                self._log("=" * 60)
                self._log(
                    f"Token usage — Prompt: {self.token_usage['prompt']}, "
                    f"Completion: {self.token_usage['completion']}, "
                    f"Total: {self.token_usage['total']}"
                )
                return assistant_msg.content

            # Execute all tool calls from this turn
            for tool_call in assistant_msg.tool_calls:
                fn_name = tool_call.function.name
                try:
                    fn_args = json.loads(tool_call.function.arguments)
                except json.JSONDecodeError:
                    fn_args = {}

                self._log(f"  Action: {fn_name}({json.dumps(fn_args)})")

                # Execute with timeout
                try:
                    result = self.tools[fn_name](**fn_args)
                    result_str = json.dumps(result) if not isinstance(result, str) else result
                except KeyError:
                    result_str = json.dumps({"error": f"Unknown tool: {fn_name}"})
                except Exception as e:
                    result_str = json.dumps({"error": str(e)})

                self.messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": result_str,
                })

        self._log("\n[WARNING] Max iterations reached.")
        return "[Agent] Stopped after reaching maximum iterations."

# --- Example usage with a research assistant ---

research_agent = ReActAgent(
    system_prompt=(
        "You are a research assistant. Think step-by-step about the user's question. "
        "Use the available tools to gather information before giving your final answer. "
        "Always cite the source of your information."
    ),
    max_iterations=8,
)

@research_agent.tool(
    "search_web",
    "Search the web for information on a topic. Returns a list of results with titles and snippets.",
    {
        "type": "object",
        "properties": {
            "query": {"type": "string", "description": "Search query"},
        },
        "required": ["query"],
    },
)
def search_web(query: str) -> list[dict]:
    """Simulated web search — replace with real API in production."""
    # In production, use: requests.get("https://api.your-search.com/search", params={"q": query})
    return [
        {"title": f"Result 1 for '{query}'", "snippet": f"The capital of the country related to {query} is..."},
        {"title": f"Result 2 for '{query}'", "snippet": f"According to recent data about {query}..."},
    ]

@research_agent.tool(
    "get_page_content",
    "Fetch and return the full text content of a web page URL.",
    {
        "type": "object",
        "properties": {
            "url": {"type": "string", "description": "The URL to fetch"},
        },
        "required": ["url"],
    },
)
def get_page_content(url: str) -> str:
    """Simulated page fetch — replace with real HTTP request in production."""
    return f"Full content of {url}:\n\nThis is a detailed article with in-depth information about the topic..."

answer = research_agent.run("What are the key differences between transformers and RNNs in NLP?")
print(f"\n\nFINAL ANSWER:\n{answer}")
```
